function tableExists($conn, $table) {
    static $cache = [];
    $table = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$table);
    if ($table === '') return false;
    if (isset($cache[$table])) return $cache[$table];

    $stmt = $conn->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?");
    if (!$stmt) return false;
    $stmt->bind_param('s', $table);
    $stmt->execute();
    $res = $stmt->get_result();
    $row = $res ? $res->fetch_row() : [0];
    $stmt->close();

    $cache[$table] = ((int)($row[0] ?? 0) > 0);
    return $cache[$table];
}

function columnExists($conn, $table, $column) {
    static $cache = [];
    $table = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$table);
    $column = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$column);
    if ($table === '' || $column === '') return false;

    $key = $table . '.' . $column;
    if (isset($cache[$key])) return $cache[$key];

    $stmt = $conn->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?");
    if (!$stmt) return false;
    $stmt->bind_param('ss', $table, $column);
    $stmt->execute();
    $res = $stmt->get_result();
    $row = $res ? $res->fetch_row() : [0];
    $stmt->close();

    $cache[$key] = ((int)($row[0] ?? 0) > 0);
    return $cache[$key];
}

function barcodeBars($code) {
    $code = (string)$code;
    if ($code === '') $code = '000000';
    $seed = crc32($code);
    $html = '';
    for ($i = 0; $i < 42; $i++) {
        $w = (($seed >> ($i % 16)) & 3) + 1;
        if ($i % 7 === 0) $w = 3;
        $html .= '<span class="bar" style="width:' . $w . 'px"></span>';
    }
    return $html;
}

function numberToWords($number) {
    $number = (int)round($number);
    if ($number === 0) return 'ZERO';

    $ones = [
        0 => '', 1 => 'ONE', 2 => 'TWO', 3 => 'THREE', 4 => 'FOUR', 5 => 'FIVE',
        6 => 'SIX', 7 => 'SEVEN', 8 => 'EIGHT', 9 => 'NINE', 10 => 'TEN',
        11 => 'ELEVEN', 12 => 'TWELVE', 13 => 'THIRTEEN', 14 => 'FOURTEEN',
        15 => 'FIFTEEN', 16 => 'SIXTEEN', 17 => 'SEVENTEEN', 18 => 'EIGHTEEN', 19 => 'NINETEEN'
    ];
    $tens = [
        2 => 'TWENTY', 3 => 'THIRTY', 4 => 'FORTY', 5 => 'FIFTY',
        6 => 'SIXTY', 7 => 'SEVENTY', 8 => 'EIGHTY', 9 => 'NINETY'
    ];

    $wordsUnderThousand = function($n) use (&$wordsUnderThousand, $ones, $tens) {
        $words = [];
        if ($n >= 100) {
            $words[] = $ones[intdiv($n, 100)] . ' HUNDRED';
            $n %= 100;
        }
        if ($n >= 20) {
            $words[] = $tens[intdiv($n, 10)];
            $n %= 10;
        }
        if ($n > 0) {
            $words[] = $ones[$n];
        }
        return implode(' ', array_filter($words));
    };

    $parts = [];
    $units = [
        1000000000 => 'BILLION',
        1000000    => 'MILLION',
        1000       => 'THOUSAND'
    ];

    foreach ($units as $value => $label) {
        if ($number >= $value) {
            $count = intdiv($number, $value);
            $parts[] = $wordsUnderThousand($count) . ' ' . $label;
            $number %= $value;
        }
    }

    if ($number > 0) {
        $parts[] = $wordsUnderThousand($number);
    }

    return implode(' ', array_filter($parts));
}

function initialsFromName($name) {
    $name = trim((string)$name);
    if ($name === '') return 'RV';
    $words = preg_split('/\s+/u', $name, -1, PREG_SPLIT_NO_EMPTY);
    $initials = '';
    foreach ($words as $word) {
        $initials .= mb_strtoupper(mb_substr($word, 0, 1, 'UTF-8'), 'UTF-8');
        if (mb_strlen($initials, 'UTF-8') >= 2) break;
    }
    if ($initials === '') {
        $initials = mb_strtoupper(mb_substr($name, 0, 2, 'UTF-8'), 'UTF-8');
    }
    return $initials;
}

function resolveLogoPath($conn, $shop_id) {
    $candidates = [];

    if (tableExists($conn, 'shops')) {
        foreach (['logo', 'shop_logo', 'image', 'photo'] as $col) {
            if (columnExists($conn, 'shops', $col)) {
                $sql = "SELECT `$col` AS logo_path FROM shops WHERE id = ? LIMIT 1";
                $stmt = $conn->prepare($sql);
                if ($stmt) {
                    $stmt->bind_param('i', $shop_id);
                    $stmt->execute();
                    $row = $stmt->get_result()->fetch_assoc();
                    $stmt->close();
                    if (!empty($row['logo_path'])) {
                        $dbPath = trim((string)$row['logo_path']);
                        $candidates[] = $dbPath;
                        $candidates[] = '../' . ltrim($dbPath, '/');
                        $candidates[] = '../../' . ltrim($dbPath, '/');
                        $candidates[] = '../uploads/' . basename($dbPath);
                    }
                }
            }
        }
    }

    $candidates = array_merge($candidates, [
        '../assets/logo.png',
        '../assets/logo.jpg',
        '../assets/logo.jpeg',
        '../uploads/logo.png',
        '../uploads/logo.jpg',
        '../uploads/logo.jpeg',
        '../uploads/shop_logo.png',
        '../uploads/shop_logo.jpg',
        '../uploads/shops/' . $shop_id . '.png',
        '../uploads/shops/' . $shop_id . '.jpg',
        '../uploads/shops/logo_' . $shop_id . '.png',
        '../uploads/shops/logo_' . $shop_id . '.jpg'
    ]);

    foreach ($candidates as $path) {
        if ($path && @file_exists($path) && @is_file($path)) {
            return $path;
        }
    }

    return '';
}

/* ================= BASIC INPUT ================= */
$shop_id = tenantShopId();
$order_id = isset($_GET['id']) ? (int)$_GET['id'] : 0;
