if ($order_id <= 0 && $invoice_code === '') {
    die('Invoice id or invoice code is required. Example: invoice_pdf.php?id=1');
}

/* ================= SHOP INFO ================= */
$shop = [
    'shop_name' => 'উত্তরা খাদ্য ভান্ডার',
    'address'   => 'সেক্টর-১৪, রোড-২৩, বাসা-০২, উত্তরা ঢাকা, ১২৩০।',
    'phone'     => '01813-370808, 01799-189105',
    'email'     => 'uttarakhaddovandar@gmail.com',
    'license'   => 'TRAD/DNCC/139065/2022',
    'tagline'   => 'বিভিন্ন ব্র্যান্ডের, মিনিকেট, কাটারী, নাজির, চিনিগুড়া, বাসমতি, আঠাইশ, পাইজাম, হাসকী, সকল প্রকার চাউল পাইকারী বিক্রয়ের বিশ্বস্ত প্রতিষ্ঠান।'
];

$shopSelectCols = ['shop_name', 'phone', 'address'];
foreach (['email', 'license', 'tagline'] as $optionalCol) {
    if (columnExists($conn, 'shops', $optionalCol)) {
        $shopSelectCols[] = $optionalCol;
    }
}
$stmt_shop = $conn->prepare("SELECT " . implode(', ', $shopSelectCols) . " FROM shops WHERE id = ? LIMIT 1");
if ($stmt_shop) {
    $stmt_shop->bind_param("i", $shop_id);
    $stmt_shop->execute();
    $shop_row = $stmt_shop->get_result()->fetch_assoc();
    if ($shop_row) {
        foreach ($shop as $key => $value) {
            if (!empty($shop_row[$key])) {
                $shop[$key] = $shop_row[$key];
            }
        }
    }
    $stmt_shop->close();
}

/* ================= ORDER INFO ================= */
if ($order_id > 0) {
    $sql = "SELECT 
                o.*,
                c.name AS customer_name,
                c.shop_name AS customer_shop_name,
                c.phone AS customer_phone,
                c.address AS customer_address,
                c.opening_due,
                c.due_amount AS customer_due_balance,
                u.name AS entry_by,
                sr.sr_name AS sale_by
            FROM orders o
            LEFT JOIN customers c ON c.id = o.customer_id AND c.shop_id = o.shop_id
            LEFT JOIN users u ON u.id = o.user_id AND u.shop_id = o.shop_id
            LEFT JOIN sales_representatives sr ON sr.id = o.sr_id AND sr.shop_id = o.shop_id
            WHERE o.id = ? AND o.shop_id = ? AND o.order_source = 'pos'
            LIMIT 1";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ii", $order_id, $shop_id);
} else {
    $sql = "SELECT 
                o.*,
                c.name AS customer_name,
                c.shop_name AS customer_shop_name,
                c.phone AS customer_phone,
                c.address AS customer_address,
                c.opening_due,
                c.due_amount AS customer_due_balance,
                u.name AS entry_by,
                sr.sr_name AS sale_by
            FROM orders o
            LEFT JOIN customers c ON c.id = o.customer_id AND c.shop_id = o.shop_id
            LEFT JOIN users u ON u.id = o.user_id AND u.shop_id = o.shop_id
            LEFT JOIN sales_representatives sr ON sr.id = o.sr_id AND sr.shop_id = o.shop_id
            WHERE o.invoice_no = ? AND o.shop_id = ? AND o.order_source = 'pos'
            LIMIT 1";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("si", $invoice_code, $shop_id);
}

if (!$stmt) {
    die('Order query prepare failed: ' . $conn->error);
}

$stmt->execute();
$order = $stmt->get_result()->fetch_assoc();
$stmt->close();

if (!$order) {
    die('Invoice not found.');
}

$order_id = (int)$order['id'];
$invoice_no = cleanInvoiceNo($order['invoice_no']);

/* ================= ITEMS ================= */
$items = [];
$total_qty = 0.0;
$items_sql = "SELECT 
                oi.*,
                p.product_name,
                p.unit
              FROM order_items oi
              INNER JOIN orders o ON o.id = oi.order_id
              LEFT JOIN products p ON p.id = oi.product_id AND p.shop_id = o.shop_id
              WHERE oi.order_id = ? AND o.shop_id = ? AND o.order_source = 'pos'
              ORDER BY oi.id ASC";
$stmt_items = $conn->prepare($items_sql);
$stmt_items->bind_param("ii", $order_id, $shop_id);
$stmt_items->execute();
$result_items = $stmt_items->get_result();
while ($row = $result_items->fetch_assoc()) {
    $items[] = $row;
    $total_qty += (float)$row['qty'];
}
$stmt_items->close();

/* ================= CALCULATION ================= */
$subtotal = (float)($order['subtotal'] ?? 0);
$discount = (float)($order['discount'] ?? 0);
$delivery_cost = (float)($order['delivery_cost'] ?? 0);
$group_unit_cost = (float)($order['group_unit_cost'] ?? 0);
$total_amount = (float)($order['total_amount'] ?? 0);
$paid_amount = (float)($order['paid_amount'] ?? 0);
$current_due = (float)($order['due_amount'] ?? 0);

if ($subtotal <= 0 && !empty($items)) {
    foreach ($items as $it) {
        $subtotal += (float)$it['subtotal'];
    }
}
if ($total_amount <= 0) {
    $total_amount = max(0, $subtotal - $discount + $delivery_cost + $group_unit_cost);
}
if ($current_due <= 0 && $total_amount > 0) {
    $current_due = max(0, $total_amount - $paid_amount);
}

$opening_due = (float)($order['opening_due'] ?? 0);
$customer_due_balance = (float)($order['customer_due_balance'] ?? 0);
$total_customer_due_now = $opening_due + $customer_due_balance;
$pre_due = max(0, $total_customer_due_now - $current_due);
$total_due = $pre_due + $current_due;

$date_text = !empty($order['created_at']) ? date('d-M-Y', strtotime($order['created_at'])) : date('d-M-Y');
$top_datetime = !empty($order['created_at']) ? date('d/m/Y, H:i', strtotime($order['created_at'])) : date('d/m/Y, H:i');
$customer_display = $order['customer_shop_name'] ?: $order['customer_name'] ?: 'Walk In Customer';
$current_url = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ? 'https://' : 'http://') . ($_SERVER['HTTP_HOST'] ?? '') . ($_SERVER['REQUEST_URI'] ?? '');
$logo_path = resolveLogoPath($conn, $shop_id);
$embedded_logo_data_uri = 'data:image/png;base64,';
$logo_initials = initialsFromName($shop['shop_name']);
$payment_method = trim((string)($order['payment_method'] ?? 'Cash'));
$invoice_status = $current_due > 0 ? 'Due' : 'Paid';
?>
